const d = $('When Executed by Another Workflow').first().json;
const FOUNDER_EMAIL = 'nexcraftcreativestudio@gmail.com';
const m = n => 'N' + (Number(n) / 1e6).toFixed(2) + 'm';
const type = d.message_type || d.risk_state || 'DAILY_SUMMARY';

const subjects = {
  WATCH: 'WATCH: BrightPath cash is trending toward the safety buffer',
  AT_RISK: 'URGENT: BrightPath cash is AT RISK',
  CRITICAL: 'CRITICAL: BrightPath cash alert',
  DAILY_SUMMARY: 'BrightPath daily cashflow summary'
};
const subject = subjects[type] || subjects.DAILY_SUMMARY;

const fallbackNote = d.ai_source === 'fallback'
  ? '<p><b>Automated summary: the AI service was unavailable, so this alert was built from the forecast figures.</b></p>' : '';
const actions = Array.isArray(d.actions) && d.actions.length
  ? '<p><b>Recommended actions</b></p><ol>' + d.actions.map(a => `<li>${a}</li>`).join('') + '</ol>' : '';

const html = `
<h2>${subject}</h2>
${fallbackNote}
<p><b>Status:</b> ${d.risk_state || type}${d.urgency ? ' (urgency: ' + d.urgency + ')' : ''}</p>
<ul>
  <li>Current cash: ${d.current_cash != null ? m(d.current_cash) : 'n/a'}</li>
  <li>Lowest projected balance: ${m(d.minimum_projected_balance)} on Day ${d.day_of_minimum}</li>
  <li>Safety buffer: N4.00m</li>
  <li>Days to breach: ${d.days_to_breach ?? 'none'}</li>
</ul>
${d.summary ? '<p><b>Summary:</b> ' + d.summary + '</p>' : ''}
${d.cause ? '<p><b>Cause:</b> ' + d.cause + '</p>' : ''}
${actions}
<p style="color:#888">BrightPath Early Warning System | Run ${d.run_id || ''}</p>`;

return [{ json: { to: d.to || FOUNDER_EMAIL, subject, html, message_type: type } }];

const sent = $input.first().json;
const built = $('Build Email').first().json;
return [{ json: { sent: true, message_id: sent.id, message_type: built.message_type } }];
